return {["scripts/actions/abilities/pets/gloeosuccus.lua"]={["Path"]="scripts/actions/abilities/pets/gloeosuccus.lua",["SHA256"]="0f1cae922bafc8e9dd98d45b6d265964651605d95692c492d33f2bc90a01c399",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'gloeosuccus_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/grand_fall.lua"]={["Path"]="scripts/actions/abilities/pets/grand_fall.lua",["SHA256"]="6c0d767162d022b42549a6b5b7e9126152c0e4a5064ee6bc509c2f94f2ea0568",["Text"]="-----------------------------------\n-- Grand Fall\n-- Family: Leviathan (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- Merit TP bonus.\n    local merits = 0\n\n    if summoner and summoner:isPC() then\n        merits = utils.clamp(summoner:getMerit(xi.merit.GRANDFALL) - 400, 0, 3000)\n    end\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 5.3570, 8.0273, 10.7031 }\n    params.fTPBonus        = merits\n    params.int_wSC         = 0.30\n    params.element         = xi.element.WATER\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.WATER\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/grapple.lua"]={["Path"]="scripts/actions/abilities/pets/grapple.lua",["SHA256"]="23334f46b0d1659723d01824f34e11d6b9f60729db4f5d6dff725f767b8e8928",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'grapple_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/gust_breath.lua"]={["Path"]="scripts/actions/abilities/pets/gust_breath.lua",["SHA256"]="2dd9250eb43704577fe198af07d6836d0cf28df76a9b57d822f751b40b4ef2f2",["Text"]="-----------------------------------\n-- Gust Breath\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    return xi.job_utils.dragoon.useDamageBreath(pet, target, petskill, action, xi.damageType.WIND)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/harden_shell.lua"]={["Path"]="scripts/actions/abilities/pets/harden_shell.lua",["SHA256"]="f3567e8e20f69fc8ed9649caa35f14bd5383a35fb7c8ecef27fefc5befd41d9b",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'harden_shell_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/hastega.lua"]={["Path"]="scripts/actions/abilities/pets/hastega.lua",["SHA256"]="94396c5dba9cca871e786611158004d4beeb824abd2812dd233d1a45935878b3",["Text"]="-----------------------------------\n-- Hastega\n-- Family: Avatar (Garuda)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local baseDuration = 180\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n\n    -- Old Notes:\n    -- Garuda's Hastega is a weird exception and uses 153/1024 instead of 150/1024 like Haste spell\n    -- That's why it overwrites some things regular haste won't. 153/1024 ~14.94%\n\n    -- Note from retail capture: WHM Haste spell and Garuda's Hastega will overwrite eachother.\n    if target:addStatusEffect(xi.effect.HASTE, { power = 1494, duration = duration, origin = pet }) then\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n        else\n            petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        end\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        return\n    end\n\n    return xi.effect.HASTE\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/head_butt.lua"]={["Path"]="scripts/actions/abilities/pets/head_butt.lua",["SHA256"]="d0849e91b0ae494208171367969eb924205123329b7b1778234eb4c3a9ec21b8",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'head_butt_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/healing_breath.lua"]={["Path"]="scripts/actions/abilities/pets/healing_breath.lua",["SHA256"]="e40eab8836a879f9177a78298517c2606326b57701599ff5ae9911d8b6a7bf85",["Text"]="-----------------------------------\n-- Healing Breath I\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    return xi.job_utils.dragoon.useHealingBreath(pet, target, petskill, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/healing_breath_ii.lua"]={["Path"]="scripts/actions/abilities/pets/healing_breath_ii.lua",["SHA256"]="f3db94924d69c1c7c21a7c491fa15581800d037d5f3b57ad50c513577735500a",["Text"]="-----------------------------------\n-- Healing Breath II\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    return xi.job_utils.dragoon.useHealingBreath(pet, target, petskill, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/healing_breath_iii.lua"]={["Path"]="scripts/actions/abilities/pets/healing_breath_iii.lua",["SHA256"]="5553c6be4e07c29cb7224117e245d300dd0d68d004b1ffc5fa2ff5f1b5c58af0",["Text"]="-----------------------------------\n-- Healing Breath III\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    return xi.job_utils.dragoon.useHealingBreath(pet, target, petskill, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/healing_breath_iv.lua"]={["Path"]="scripts/actions/abilities/pets/healing_breath_iv.lua",["SHA256"]="c81025d13b94afbd833fbaa85d2e76e3e9969f5cabe5525ef7e34f4f04fa1048",["Text"]="-----------------------------------\n-- Healing Breath IV\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    return xi.job_utils.dragoon.useHealingBreath(pet, target, petskill, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/healing_ruby.lua"]={["Path"]="scripts/actions/abilities/pets/healing_ruby.lua",["SHA256"]="61f429dc94031fe3ecf0625483b09d64690bec11f5056ec451ac73ed5daffdb8",["Text"]="-----------------------------------\n-- Healing Ruby\n-- Family: Avatar (Carbuncle)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.primaryMessage = xi.msg.basic.JA_RECOVERS_HP_2\n    params.baseHeal       = 3 * (pet:getMainLvl() - 30)\n    params.additiveHeal   = 44\n    params.fTP =\n    {\n        { tp = 0,    modifier = 256 / 256 },\n        { tp = 1500, modifier = 351 / 256 },\n        { tp = 3000, modifier = 446 / 256 },\n    }\n\n    if pet:getMainLvl() <= 30 then\n        params.baseHeal     = pet:getMainLvl()\n        params.additiveHeal = 14\n    end\n\n    -- https://wiki.ffo.jp/html/4079.html\n    -- TODO: verify retail fomula\n    -- TODO: Capture retail TP scaling\n    -- Level 82 - 302 Summoning Skill - LightningDay\n\n    -- TP: 0000  - 301 Healed\n    -- TP: 1087  - 337 Healed\n    -- TP: 2009  - 397\n    -- TP: 3000  - 482\n\n    return xi.mobskills.mobHealMove(pet, target, petskill, action, params)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/healing_ruby_ii.lua"]={["Path"]="scripts/actions/abilities/pets/healing_ruby_ii.lua",["SHA256"]="6e5edbd8d8a55d907f6f3cb4f811949360cb8ce0b289709e395f958f92bd266d",["Text"]="-----------------------------------\n-- Healing Ruby II\n-- Family: Avatar (Carbuncle)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- https://wiki.ffo.jp/html/4080.html\n    -- TODO: Capture retail TP scaling\n    -- Level 82 - 302 Summoning Skill - IceDay - 0 TP: 733 Healed\n    -- TP: 1042 - 843 Healed\n    -- TP 2000~ - 964\n    -- TP 2900~ - 1072\n\n    local params = {}\n\n    params.primaryMessage = xi.msg.basic.JA_RECOVERS_HP_2\n    params.baseHeal       = pet:getMainLvl() * 4\n    params.additiveHeal   = 30\n    params.fTP =\n    {\n        { tp = 0,    modifier = 256 / 256 },\n        { tp = 1500, modifier = 299 / 256 }, -- TODO: Unconfirmed for 75 era.\n        { tp = 3000, modifier = 342 / 256 },\n    }\n\n    return xi.mobskills.mobHealMove(pet, target, petskill, action, params)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/heavenly_strike.lua"]={["Path"]="scripts/actions/abilities/pets/heavenly_strike.lua",["SHA256"]="d5914f5e79c34fe6b85d0d048aeea078611b33f3f41be91247de0bf86dcab2ce",["Text"]="-----------------------------------\n-- Heavenly Strike\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- Merit TP bonus.\n    local merits = 0\n\n    if summoner and summoner:isPC() then\n        merits = utils.clamp(summoner:getMerit(xi.merit.HEAVENLY_STRIKE) - 400, 0, 3000)\n    end\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 5.3570, 8.0273, 10.7031 }\n    params.fTPBonus        = merits\n    params.int_wSC         = 0.30\n    params.element         = xi.element.ICE\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.ICE\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/hi-freq_field.lua"]={["Path"]="scripts/actions/abilities/pets/hi-freq_field.lua",["SHA256"]="d2463c8ee305da7972175b4c5f5a924cf78859357a552627b5de790c7642c02b",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'hi-freq_field_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/holy_mist.lua"]={["Path"]="scripts/actions/abilities/pets/holy_mist.lua",["SHA256"]="88ee880144a115b739604370a085b756832aedf97a487482d7ed0a17209420ab",["Text"]="-----------------------------------\n-- Holy Mist\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    local dint = pet:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local dmg = 600 + dint * 1.5 + petskill:getTP() / 20\n\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    target:updateEnmityFromDamage(pet, dmg)\n    target:takeDamage(dmg, pet, xi.attackType.MAGICAL, xi.damageType.LIGHT)\n    return dmg\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/hoof_volley.lua"]={["Path"]="scripts/actions/abilities/pets/hoof_volley.lua",["SHA256"]="2429576407fc373fe4ba574d0c22d1372100211cb7d8ceb53b53f3be5a5cf457",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'hoof_volley_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/howling_moon.lua"]={["Path"]="scripts/actions/abilities/pets/howling_moon.lua",["SHA256"]="83035a4002829e6e0391466e0181a1a809151735ea130cb342e739cc51d578a5",["Text"]="-----------------------------------\n-- Howling Moon\n-- Family: Fenrir (Player Pet)\n-- Note: Fenrir's Astral Flow\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 9.0, 9.0, 9.0 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.DARK\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.DARK\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n    -- TODO: Should not consume TP\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    summoner:setMP(0)\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/hydro_breath.lua"]={["Path"]="scripts/actions/abilities/pets/hydro_breath.lua",["SHA256"]="852b4dbf398ff61cc52ab82838c71d9d9e13bd0c5e0f51112669490ff32c3edf",["Text"]="-----------------------------------\n-- Hydro Breath\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    return xi.job_utils.dragoon.useDamageBreath(pet, target, petskill, action, xi.damageType.WATER)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/hysteric_assault.lua"]={["Path"]="scripts/actions/abilities/pets/hysteric_assault.lua",["SHA256"]="28a14826a8c51142edcf382a606db93cce46b82e918a9b73ecd5265fc6918155",["Text"]="-----------------------------------\n-- Hysteric Assault\n-- Family: Avatar (Siren)\n-- Description: Delivers a threefold attack. Additional Effect: HP Drain\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\n-- http://wiki.ffo.jp/html/37933.html\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 3\n    params.fTP               = { 5.0, 5.0, 5.0 } -- TODO: Capture fTPs\n    params.fTPSubsequentHits = { 5.0, 5.0, 5.0 }\n    -- TODO: Capture wSCs\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.PIERCING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_3\n    params.canCrit           = true\n    params.criticalChance    = { 0.10, 0.20, 0.25 } -- TODO: Capture crit rate\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, xi.attackType.PHYSICAL, xi.damageType.PIERCING)\n\n        pet:addHP(info.damage) -- This is like Sanguine Blade: https://www.bg-wiki.com/ffxi/Hysteric_Assault\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/inferno.lua"]={["Path"]="scripts/actions/abilities/pets/inferno.lua",["SHA256"]="ea62edbc3c3882db6290670daa9d4d250800d03bea83476d058cea52d9ab7ee1",["Text"]="-----------------------------------\n-- Inferno\n-- Family: Ifrit (Player Pet)\n-- Note: Ifrit's Astral Flow\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 9.0, 9.0, 9.0 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.FIRE\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.FIRE\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n    -- TODO: Should not consume TP\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    summoner:setMP(0)\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/infrasonics.lua"]={["Path"]="scripts/actions/abilities/pets/infrasonics.lua",["SHA256"]="5b380f46d731b7329132c99c3f83e9215108ad6511d4fa581bd3bf2678799db7",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'infrasonics_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/intimidate.lua"]={["Path"]="scripts/actions/abilities/pets/intimidate.lua",["SHA256"]="284d81d338cbdc33881cdcd9152c9def17b6712f247a99db056393f179aa6609",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'intimidate_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/jettatura.lua"]={["Path"]="scripts/actions/abilities/pets/jettatura.lua",["SHA256"]="0f5f69b32ef6822f6c9cf3a9d8f06c987040fff8ca5352cf1a87fbb6e8f5fafc",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'jettatura_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/judgment_bolt.lua"]={["Path"]="scripts/actions/abilities/pets/judgment_bolt.lua",["SHA256"]="a9d19a3616b3487121a790497252ec098c3e8b5d9bdc3a2b628498775b5c406c",["Text"]="-----------------------------------\n-- Judgment Bolt\n-- Family: Ramuh (Player Pet)\n-- Note: Ramuh's Astral Flow\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 9.0, 9.0, 9.0 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.THUNDER\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.THUNDER\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n    -- TODO: Should not consume TP\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    summoner:setMP(0)\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/lamb_chop.lua"]={["Path"]="scripts/actions/abilities/pets/lamb_chop.lua",["SHA256"]="232a5f961d206b769ed28e5e944c42b87d921e476703d2f5783851a7b9bc7fe9",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'lamb_chop_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/leaf_dagger.lua"]={["Path"]="scripts/actions/abilities/pets/leaf_dagger.lua",["SHA256"]="da92c75ad2dc66217c1f919e6e1fa66f4b7ed175623a7aa669d4d3492a05f711",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'leaf_dagger_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/level_X_holy.lua"]={["Path"]="scripts/actions/abilities/pets/level_X_holy.lua",["SHA256"]="67f22fd14e87814c61465e536e59294fd9d713e6311202a55c74fc3e00d232e1",["Text"]="-----------------------------------\n-- Level X Holy\n-- Family: Cait sith (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local holyRollOneAnimID = 164\n    local primaryTargetID   = action:getPrimaryTargetID()\n\n    -- If primary target, roll for power by setting random animation.\n    -- We do this so the animation is random, but only rolled for once. (AKA: The same for all targets)\n    if primaryTargetID == target:getID() then\n        action:setAnimation(primaryTargetID, holyRollOneAnimID + math.randomInt(0, 5))\n    else\n        local animationId = action:getAnimation(primaryTargetID)\n        if animationId then\n            action:setAnimation(target:getID(), animationId)\n        end\n    end\n\n    local power = action:getAnimation(target:getID()) - 163\n\n    local params = {}\n\n    params.baseDamage       = pet:getMainLvl()\n    params.fTP              = { power, power, power }\n    -- TODO: wSCs?\n    params.element          = xi.element.LIGHT\n    params.attackType       = xi.attackType.MAGICAL\n    params.damageType       = xi.damageType.LIGHT\n    params.shadowBehavior   = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier  = 1.5\n    params.dStatAttackerMod = xi.mod.MND\n    params.dStatDefenderMod = xi.mod.MND\n    params.canMagicBurst    = true\n    params.primaryMessage   = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    -- Only have an effect if target's level is divisible by die roll\n    if target:getMainLvl() % power == 0 then\n        if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n            target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n        end\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/lightning_armor.lua"]={["Path"]="scripts/actions/abilities/pets/lightning_armor.lua",["SHA256"]="41711fa8f0f5f5e4ecb63a54524616e05ffe9e2e0289d8380031a6b29d6598b4",["Text"]="-----------------------------------\n-- Lightning Armor\n-- Family: Avatar (Ramuh)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    local baseDuration = 180\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    target:delStatusEffect(xi.effect.SHOCK_SPIKES)\n\n    -- TODO: Does power scale?\n    if target:addStatusEffect(xi.effect.SHOCK_SPIKES, { power = 15, duration = duration, origin = pet }) then\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n        else\n            petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        end\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        return\n    end\n\n    return xi.effect.SHOCK_SPIKES\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/lightning_breath.lua"]={["Path"]="scripts/actions/abilities/pets/lightning_breath.lua",["SHA256"]="b22ac59618cd5fe18297148476e0824bb032f0c33afe90af327d994baa248569",["Text"]="-----------------------------------\n-- Lightning Breath\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    return xi.job_utils.dragoon.useDamageBreath(pet, target, petskill, action, xi.damageType.THUNDER)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/lunar_cry.lua"]={["Path"]="scripts/actions/abilities/pets/lunar_cry.lua",["SHA256"]="f4fcdf8d66c70269c586d16642f6f31db156b3b81be4c6276e19adca867a1e76",["Text"]="-----------------------------------\n-- Lunar Cry\n-- Family: Avatar (Fenrir)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local moonCycle = getVanadielMoonCycle()\n\n    local cycleBuffs =\n    {\n        [xi.moonCycle.NEW_MOON]                = 1,\n        [xi.moonCycle.LESSER_WAXING_CRESCENT]  = 6,\n        [xi.moonCycle.GREATER_WAXING_CRESCENT] = 11,\n        [xi.moonCycle.FIRST_QUARTER]           = 16,\n        [xi.moonCycle.LESSER_WAXING_GIBBOUS]   = 21,\n        [xi.moonCycle.GREATER_WAXING_GIBBOUS]  = 26,\n        [xi.moonCycle.FULL_MOON]               = 31,\n        [xi.moonCycle.GREATER_WANING_GIBBOUS]  = 26,\n        [xi.moonCycle.LESSER_WANING_GIBBOUS]   = 21,\n        [xi.moonCycle.THIRD_QUARTER]           = 16,\n        [xi.moonCycle.GREATER_WANING_CRESCENT] = 11,\n        [xi.moonCycle.LESSER_WANING_CRESCENT]  = 6,\n    }\n\n    local buffValue = cycleBuffs[moonCycle]\n\n    -- TODO: Fenrir's Lunar Cry does not overwrite itself. Unknown interactions with other Accuracy Down/Evasion Down effects.\n\n    local baseDuration = 180 -- TODO: Capture retail baseDuration\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n\n    local effectTable =\n    {\n        [1] = { effectId = xi.effect.ACCURACY_DOWN, power = buffValue, origin = pet, duration = duration, tier = 1, magicalElement = xi.element.DARK },\n        [2] = { effectId = xi.effect.EVASION_DOWN, power = 32 - buffValue, origin = pet, duration = duration, tier = 1, magicalElement = xi.element.DARK },\n    }\n\n    -- Skill has a unique message that is not tied to one status effect.\n    petskill:setMsg(xi.msg.basic.ACC_EVA_DOWN)\n\n    return xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/lunar_roar.lua"]={["Path"]="scripts/actions/abilities/pets/lunar_roar.lua",["SHA256"]="65497048982ca2d3db4b4b19b2679b0380b67d7c392b795a33492ce56c0d3c39",["Text"]="-----------------------------------\n-- Lunar Roar\n-- Family: Avatar (Fenrir)\n-- Note: Ability range was increased in Sept. 6, 2016 update:\n-- https://wiki.ffo.jp/html/35741.html\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- TODO: Can this dispel be resisted?\n    local effect = target:dispelStatusEffect()\n    if effect == xi.effect.NONE then\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n    else\n        for i = 1, 2 do\n            if not target:dispelStatusEffect(xi.effectFlag.DISPELABLE) then\n                break\n            end\n        end\n\n        petskill:setMsg(xi.msg.basic.NONE)\n    end\n\n    return 0\nend\n\nreturn abilityObject\n"}};
